(() => {
  "use strict";
  const examples = [
    {id:"seq-001",topic:"المتتاليات",unit:"المتتاليات",lesson:"المتتاليات الحسابية",level:"أساسي",question:"متتالية حسابية حدها الأول \\(u_1=7\\) وأساسها \\(r=-2\\). احسب \\(u_6\\).",keyIdea:"نستخدم الحد العام للمتتالية الحسابية مع الانتباه إلى إشارة الأساس.",steps:["قانون الحد العام هو \\(u_n=u_1+(n-1)r\\).","نعوّض: \\(u_6=7+(6-1)(-2)\\).","نحسب: \\(u_6=7-10=-3\\)."],answer:"\\(u_6=-3\\)",check:"بالتتابع: 7، 5، 3، 1، -1، -3."},
    {id:"seq-002",topic:"المتتاليات",unit:"المتتاليات",lesson:"المتتاليات الهندسية",level:"متوسط",question:"متتالية هندسية حدها الأول \\(u_1=3\\) وأساسها \\(q=2\\). احسب مجموع حدودها الخمسة الأولى.",keyIdea:"مجموع أول n حدود هندسية عندما q لا يساوي 1.",steps:["نستخدم \\(S_n=u_1\\frac{1-q^n}{1-q}\\) عندما \\(q\\ne1\\).","نعوّض: \\(S_5=3\\frac{1-2^5}{1-2}\\).","نحسب: \\(S_5=3\\frac{-31}{-1}=93\\)."],answer:"\\(S_5=93\\)",check:"الحدود هي 3، 6، 12، 24، 48 ومجموعها 93."},
    {id:"seq-003",topic:"المتتاليات",unit:"المتتاليات",lesson:"الإثبات بالتدريج",level:"متقدم",question:"أثبت بالتدريج أن \\(1+2+\\cdots+n=\\frac{n(n+1)}2\\) لكل \\(n\\ge1\\).",keyIdea:"الانتقال من صحة العبارة عند n إلى صحتها عند n+1 بعد إضافة الحد التالي.",steps:["البدء: عند \\(n=1\\)، الطرفان يساويان 1، فالعبارة صحيحة.","فرض الاستقراء: نفترض \\(1+\\cdots+n=\\frac{n(n+1)}2\\).","خطوة الانتقال: \\(1+\\cdots+n+(n+1)=\\frac{n(n+1)}2+(n+1)\\).","نأخذ \\(n+1\\) عاملاً مشتركاً فنحصل على \\(\\frac{(n+1)(n+2)}2\\)، وهي الصيغة المطلوبة عند n+1."],answer:"ثبتت العبارة لكل عدد طبيعي موجب.",check:"البرهان يتضمن البدء وفرض الاستقراء وخطوة الانتقال."},
    {id:"lim-001",topic:"النهايات والاستمرار",unit:"التوابع والنهايات والاستمرار",lesson:"نهاية تابع عند عدد حقيقي",level:"أساسي",question:"احسب \\(\\lim_{x\\to2}(3x^2-x+1)\\).",keyIdea:"كثير الحدود مستمر عند كل عدد حقيقي، لذا نحسب النهاية بالتعويض المباشر.",steps:["التعبير كثير حدود، وهو مستمر على \\(\\mathbb R\\).","نعوّض \\(x=2\\): \\(3(2)^2-2+1\\).","نحسب: \\(12-2+1=11\\)."],answer:"\\(11\\)",check:"التعويض المباشر جائز لأن الدالة كثيرة حدود."},
    {id:"lim-002",topic:"النهايات والاستمرار",unit:"التوابع والنهايات والاستمرار",lesson:"النهايات غير المعينة والتحليل",level:"متوسط",question:"احسب \\(\\lim_{x\\to3}\\frac{x^2-9}{x-3}\\).",keyIdea:"نزيل حالة عدم التعيين بتحليل فرق مربعين ثم الاختزال ضمن المجال الذي يقترب منه x.",steps:["بالتعويض المباشر نحصل على \\(0/0\\)، وهي حالة غير معينة.","نحلل: \\(x^2-9=(x-3)(x+3)\\).","لـ \\(x\\ne3\\)، يصبح الكسر \\(x+3\\).","إذن النهاية \\(3+3=6\\)."],answer:"\\(6\\)",check:"الاختزال صحيح في جوار 3 مع استثناء x=3."},
    {id:"lim-003",topic:"النهايات والاستمرار",unit:"التوابع والنهايات والاستمرار",lesson:"المقارب المائل",level:"متقدم",question:"أوجد المقارب المائل للتابع \\(f(x)=\\frac{x^2+2x+3}{x+1}\\) عندما \\(x\\to\\pm\\infty\\).",keyIdea:"القسمة الإقليدية تكتب التابع على صورة مستقيم زائد كسر يؤول إلى الصفر.",steps:["نقسم \\(x^2+2x+3\\) على \\(x+1\\)، فنحصل على \\(x+1\\) والباقي 2.","إذن \\(f(x)=x+1+\\frac{2}{x+1}\\).","عندما \\(x\\to\\pm\\infty\\)، فإن \\(\\frac{2}{x+1}\\to0\\)."],answer:"المقارب المائل هو \\(y=x+1\\).",check:"الفرق بين f(x) و x+1 يؤول إلى الصفر."},
    {id:"der-001",topic:"الاشتقاق",unit:"الاشتقاق",lesson:"اشتقاق مجموع توابع",level:"أساسي",question:"إذا كان \\(f(x)=4x^3-5x^2+2x-7\\)، أوجد \\(f'(x)\\).",keyIdea:"نشتق حدود كثير الحدود حدّاً حدّاً باستعمال قاعدة القوة.",steps:["\\((4x^3)'=12x^2\\).","\\((-5x^2)'=-10x\\) و\\((2x)'=2\\).","مشتقة الثابت \\(-7\\) تساوي صفراً."],answer:"\\(f'(x)=12x^2-10x+2\\)",check:"درجة كل حد مشتق تنقص واحداً، والثابت يختفي."},
    {id:"der-002",topic:"الاشتقاق",unit:"الاشتقاق",lesson:"اشتقاق تابع مركب",level:"متوسط",question:"اشتق \\(f(x)=(2x+1)^5\\).",keyIdea:"قاعدة اشتقاق المركب: مشتقة القوة الخارجية مضروبة بمشتقة الداخل.",steps:["نضع \\(u=2x+1\\)، فيكون \\(f=u^5\\).","مشتقة \\(u^5\\) بالنسبة إلى u هي \\(5u^4\\)، ومشتقة u هي 2.","إذن \\(f'(x)=5(2x+1)^4\\cdot2\\)."],answer:"\\(f'(x)=10(2x+1)^4\\)",check:"تظهر مشتقة العبارة الداخلية 2 عاملاً في الناتج."},
    {id:"log-001",topic:"التابع اللوغاريتمي",unit:"التابع اللوغاريتمي النيبيري",lesson:"مجال التعريف",level:"أساسي",question:"حدد مجال تعريف \\(f(x)=\\ln(2x-6)\\).",keyIdea:"يجب أن تكون حجة اللوغاريتم الطبيعي موجبة تماماً.",steps:["شرط التعريف: \\(2x-6>0\\).","نضيف 6 ثم نقسم على 2: \\(x>3\\)."],answer:"\\(D_f=]3,+\\infty[\\)",check:"لا يجوز أن تساوي حجة اللوغاريتم صفراً."},
    {id:"log-002",topic:"التابع اللوغاريتمي",unit:"التابع اللوغاريتمي النيبيري",lesson:"خواص اللوغاريتم",level:"متوسط",question:"بسّط \\(\\ln(5)+\\ln(4)-\\ln(2)\\).",keyIdea:"نستعمل خواص جمع اللوغاريتمات وطرحها مع أعداد موجبة.",steps:["\\(\\ln(5)+\\ln(4)=\\ln(20)\\).","\\(\\ln(20)-\\ln(2)=\\ln(20/2)\\).","إذن الناتج \\(\\ln(10)\\)."],answer:"\\(\\ln(10)\\)",check:"كل الأعداد داخل اللوغاريتمات موجبة، وتطبيق الخواص جائز."},
    {id:"exp-001",topic:"التابع الأسي",unit:"التابع الأسي",lesson:"خواص الأسية",level:"أساسي",question:"بسّط \\(e^{3x}\\cdot e^{2-x}\\).",keyIdea:"عند ضرب قوتين لهما الأساس نفسه نجمع الأسين.",steps:["نكتب \\(e^{3x}e^{2-x}=e^{3x+2-x}\\).","نجمع الحدود المتشابهة في الأس: \\(3x-x+2=2x+2\\)."],answer:"\\(e^{2x+2}\\)",check:"الأساس ثابت e، لذلك نجمع الأسين ولا نضربهما."},
    {id:"exp-002",topic:"التابع الأسي",unit:"التابع الأسي",lesson:"حل معادلات أسية",level:"متوسط",question:"حل في \\(\\mathbb R\\): \\(e^{2x-1}=e^{x+3}\\).",keyIdea:"الدالة الأسية تقابلية، فتتساوى الأسس عندما تتساوى القيم.",steps:["بما أن \\(e^a=e^b\\) فإن \\(a=b\\).","نساوي الأسين: \\(2x-1=x+3\\).","بطرح x وإضافة 1 نحصل على \\(x=4\\)."],answer:"\\(x=4\\)",check:"بالتعويض يصبح الأس في الطرفين 7."},
    {id:"int-001",topic:"التكامل والتابع الأصلي",unit:"التكامل والتوابع الأصلية",lesson:"التوابع الأصلية",level:"أساسي",question:"أوجد التابع الأصلي الذي يحقق \\(F'(x)=6x-4\\) و\\(F(0)=3\\).",keyIdea:"نوجد عائلة التوابع الأصلية ثم نستخدم الشرط الابتدائي لتحديد الثابت.",steps:["تابع أصلي لـ \\(6x-4\\) هو \\(F(x)=3x^2-4x+C\\).","من الشرط \\(F(0)=3\\): \\(C=3\\)."],answer:"\\(F(x)=3x^2-4x+3\\)",check:"اشتقاق الناتج يعطي 6x-4، وقيمته عند الصفر 3."},
    {id:"int-002",topic:"التكامل والتابع الأصلي",unit:"التكامل والتوابع الأصلية",lesson:"التكامل المحدد",level:"متوسط",question:"احسب \\(\\int_1^3 2x\\,dx\\).",keyIdea:"نستخدم تابعاً أصلياً ثم قاعدة بارو.",steps:["تابع أصلي لـ \\(2x\\) هو \\(F(x)=x^2\\).","نطبق قاعدة بارو: \\(F(3)-F(1)\\).","نحسب \\(9-1=8\\)."],answer:"\\(8\\)",check:"مشتقة x² تساوي 2x."},
    {id:"vec-001",topic:"الأشعة في الفراغ",unit:"الأشعة في الفراغ",lesson:"المركبات والإحداثيات",level:"أساسي",question:"في معلم متعامد، إذا كانت \\(A(1,-2,3)\\) و\\(B(4,0,-1)\\)، أوجد مركبات \\(\\overrightarrow{AB}\\).",keyIdea:"مركبات الشعاع من A إلى B هي إحداثيات B ناقص إحداثيات A.",steps:["نحسب المركبة الأولى: \\(4-1=3\\).","الثانية: \\(0-(-2)=2\\)، والثالثة: \\(-1-3=-4\\)."],answer:"\\(\\overrightarrow{AB}=(3,2,-4)\\)",check:"نجمع مركبات الشعاع إلى A فنحصل على B."},
    {id:"dot-001",topic:"الجداء السلمي في الفراغ",unit:"الجداء السلمي في الفراغ",lesson:"الجداء السلمي بالإحداثيات",level:"أساسي",question:"احسب جداء الشعاعين \\(\\vec u=(2,-1,3)\\) و\\(\\vec v=(1,4,-2)\\).",keyIdea:"نضرب المركبات المتناظرة ثم نجمع النواتج.",steps:["\\(\\vec u\\cdot\\vec v=2(1)+(-1)(4)+3(-2)\\).","نحسب: \\(2-4-6=-8\\)."],answer:"\\(-8\\)",check:"عدد المركبات ثلاث، وكل مركبة ضُربت بنظيرتها."},
    {id:"line-001",topic:"المستقيمات والمستويات في الفراغ",unit:"المستقيمات والمستويات في الفراغ",lesson:"المعادلة الديكارتية لمستوى",level:"متوسط",question:"اكتب معادلة المستوى المار بالنقطة \\(A(1,0,2)\\) والناظم له \\(\\vec n=(2,-1,3)\\).",keyIdea:"معادلة المستوى ذي الناظم (a,b,c) المار بـ A هي a(x-xA)+b(y-yA)+c(z-zA)=0.",steps:["نطبق \\(2(x-1)-(y-0)+3(z-2)=0\\).","نفتح الأقواس: \\(2x-2-y+3z-6=0\\).","نجمع الثوابت."],answer:"\\(2x-y+3z-8=0\\)",check:"تعويض إحداثيات A يعطي صفراً."},
    {id:"cx-001",topic:"الأعداد العقدية",unit:"الأعداد العقدية",lesson:"العمليات على الأعداد العقدية",level:"أساسي",question:"احسب \\((2+3i)(1-2i)\\).",keyIdea:"نوزع الضرب ثم نستعمل العلاقة \\(i^2=-1\\).",steps:["نوزع: \\(2-4i+3i-6i^2\\).","نعوّض \\(i^2=-1\\): \\(2-i+6\\)."],answer:"\\(8-i\\)",check:"الجزء الحقيقي 8 والتخيلي -1."},
    {id:"cx-002",topic:"الأعداد العقدية",unit:"الأعداد العقدية",lesson:"الشكل المثلثي والعيار",level:"متوسط",question:"أوجد عيار العدد العقدي \\(z=-3+4i\\).",keyIdea:"عيار a+bi يساوي الجذر التربيعي لمجموع مربعي الجزأين.",steps:["نحدد \\(a=-3\\) و\\(b=4\\).","\\(|z|=\\sqrt{(-3)^2+4^2}\\).","\\(|z|=\\sqrt{9+16}=5\\)."],answer:"\\(|z|=5\\)",check:"العيار غير سالب دائماً."},
    {id:"comb-001",topic:"التحليل التوافقي",unit:"التحليل التوافقي",lesson:"التوافيق",level:"أساسي",question:"كم لجنة من ثلاثة طلاب يمكن اختيارها من مجموعة تضم 7 طلاب؟",keyIdea:"اختيار لجنة لا يعتمد على ترتيب الأعضاء، لذا نستخدم التوافيق.",steps:["نستخدم \\(\\binom{n}{k}=\\frac{n!}{k!(n-k)!}\\).","\\(\\binom73=\\frac{7!}{3!4!}=\\frac{7\\cdot6\\cdot5}{3\\cdot2\\cdot1}\\)."],answer:"\\(35\\) لجنة.",check:"لو كان الترتيب مهماً لاستخدمنا التراتيب، لكنه غير مهم هنا."},
    {id:"prob-001",topic:"الاحتمالات",unit:"الاحتمالات",lesson:"الاحتمال الشرطي",level:"متوسط",question:"إذا كان \\(P(A\\cap B)=0.2\\) و\\(P(B)=0.5\\)، احسب \\(P(A\\mid B)\\).",keyIdea:"الاحتمال الشرطي لـ A بشرط B يساوي احتمال التقاطع مقسوماً على احتمال B، إذا كان موجباً.",steps:["نكتب \\(P(A\\mid B)=\\frac{P(A\\cap B)}{P(B)}\\).","نعوّض: \\(\\frac{0.2}{0.5}=0.4\\)."],answer:"\\(P(A\\mid B)=0.4\\)",check:"الشرط P(B)>0 متحقق لأن P(B)=0.5."},
    {id:"prob-002",topic:"الاحتمالات",unit:"الاحتمالات",lesson:"المتغير العشوائي والتوقع",level:"متقدم",question:"متغير عشوائي X يأخذ القيم 0 و1 و2 باحتمالات 0.2 و0.5 و0.3 على الترتيب. احسب الأمل الرياضي.",keyIdea:"الأمل الرياضي هو مجموع جداءات كل قيمة باحتمالها.",steps:["نستخدم \\(E(X)=\\sum x_iP(X=x_i)\\).","\\(E(X)=0(0.2)+1(0.5)+2(0.3)\\).","نحسب \\(0+0.5+0.6=1.1\\)."],answer:"\\(E(X)=1.1\\)",check:"مجموع الاحتمالات 0.2+0.5+0.3=1."},
    {id:"seq-limit-001",topic:"نهاية متتالية",unit:"نهاية متتالية",lesson:"نهايات المتتاليات الكسرية",level:"أساسي",question:"احسب \\(\\lim_{n\\to+\\infty}\\frac{2n+3}{n+4}\\).",keyIdea:"في كسر كثيرتي حدود من الدرجة نفسها، النهاية هي نسبة معاملي الحدين الأعلى درجة.",steps:["نقسم البسط والمقام على \\(n\\): \\(\\frac{2+3/n}{1+4/n}\\).","عندما \\(n\\to+\\infty\\)، فإن \\(3/n\\to0\\) و\\(4/n\\to0\\).","إذن النهاية \\(\\frac{2}{1}=2\\)."],answer:"\\(2\\)",check:"الحدان من الدرجة الأولى، لذلك نأخذ نسبة المعاملين 2 و1."},
    {id:"complex-geometry-001",topic:"تطبيقات الأعداد العقدية",unit:"تطبيقات الأعداد العقدية في الهندسة",lesson:"الدوران في المستوي العقدي",level:"متوسط",question:"صورة النقطة ذات اللاحقة \\(z=2-i\\) بدوران مركزه المبدأ وزاويته \\(\\frac{\\pi}{2}\\) عكس عقارب الساعة، ما لاحقتها؟",keyIdea:"الدوران حول المبدأ بزاوية θ يضرب اللاحقة بالعدد \\(e^{i\\theta}\\). وعند θ=π/2 يكون العامل i.",steps:["عامل الدوران هو \\(e^{i\\pi/2}=i\\).","اللاحقة الجديدة \\(z'=iz=i(2-i)\\).","نوزع ونستعمل \\(i^2=-1\\): \\(z'=2i-i^2=1+2i\\)."],answer:"\\(z'=1+2i\\)",check:"العيار محفوظ بالدوران: كلا العددين عيارهما \\(\\sqrt5\\)."}
    ,
    {id:"seq-004",topic:"المتتاليات",unit:"المتتاليات",lesson:"مجموع حدود متتالية حسابية",level:"أساسي",question:"متتالية حسابية حدها الأول 4 وأساسها 3. احسب مجموع أول 10 حدود.",keyIdea:"مجموع حدود المتتالية الحسابية يساوي عدد الحدود مضروباً بمتوسط الحدين الأول والأخير.",steps:["نحسب الحد العاشر: u₁₀=4+9×3=31.","نطبق S₁₀=10(4+31)/2.","إذن S₁₀=175."],answer:"175",check:"متوسط الحدين الأول والأخير هو 17.5، وضربه في 10 يعطي 175."},
    {id:"seq-005",topic:"المتتاليات",unit:"المتتاليات",lesson:"رتابة متتالية",level:"متوسط",question:"ادرس رتابة المتتالية المعرفة بـ uₙ=2n+5 على الأعداد الطبيعية.",keyIdea:"نقارن حدين متتاليين بدراسة إشارة uₙ₊₁−uₙ.",steps:["نحسب uₙ₊₁=2(n+1)+5=2n+7.","نجد uₙ₊₁−uₙ=(2n+7)−(2n+5)=2.","بما أن الفرق موجب لكل n، فالمتتالية متزايدة تماماً."],answer:"المتتالية متزايدة تماماً.",check:"الفرق بين كل حد والذي يليه يساوي 2."},
    {id:"lim-004",topic:"النهايات والاستمرار",unit:"التوابع والنهايات والاستمرار",lesson:"استمرار تابع معرف على أجزاء",level:"متوسط",question:"لتكن f(x)=x² إذا x≤1 و f(x)=2x إذا x>1. تحقق من استمرارها عند 1.",keyIdea:"نقارن النهاية اليمنى واليسرى وقيمة التابع عند نقطة الوصل.",steps:["النهاية اليسرى عند 1 تساوي 1²=1، وقيمة f(1)=1.","النهاية اليمنى تساوي 2×1=2.","النهايتان غير متساويتين، لذلك النهاية عند 1 غير موجودة."],answer:"التابع غير مستمر عند x=1.",check:"اختلاف النهايتين الجانبيتين يكفي لنفي الاستمرار."},
    {id:"lim-005",topic:"النهايات والاستمرار",unit:"التوابع والنهايات والاستمرار",lesson:"نهايات مثلثية أساسية",level:"متقدم",question:"احسب النهاية عندما x يؤول إلى الصفر لـ sin(3x)/x، مع قياس الزوايا بالراديان.",keyIdea:"نستعمل النهاية الأساسية sin(t)/t عندما t يؤول إلى الصفر.",steps:["نكتب sin(3x)/x=3×sin(3x)/(3x).","عندما x→0 فإن 3x→0، والنهاية الأساسية تساوي 1.","إذن النهاية تساوي 3."],answer:"3",check:"النهاية الأساسية صحيحة عندما تكون الزاوية بالراديان."},
    {id:"seq-limit-002",topic:"نهاية متتالية",unit:"نهاية المتتالية",lesson:"نهاية متتالية هندسية",level:"أساسي",question:"احسب نهاية المتتالية uₙ=5(1/3)ⁿ عندما n يؤول إلى ما لا نهاية.",keyIdea:"قوى عدد حقيقي q حيث |q|<1 تؤول إلى الصفر عندما الأس يؤول إلى ما لا نهاية.",steps:["لدينا q=1/3، ومن ثم |q|<1.","إذن (1/3)ⁿ→0.","بضرب النهاية في 5 نحصل على uₙ→0."],answer:"0",check:"كل حد موجب، وتتناقص قيمته مقتربة من الصفر."},
    {id:"seq-limit-003",topic:"نهاية متتالية",unit:"نهاية المتتالية",lesson:"نهايات الجذور",level:"متوسط",question:"احسب نهاية (√(n²+4n)−n) عندما n يؤول إلى ما لا نهاية.",keyIdea:"نضرب بالمرافق لإزالة الفرق بين الجذر والحد n.",steps:["نضرب ونقسم بالمرافق: (√(n²+4n)−n)×(√(n²+4n)+n)/(√(n²+4n)+n).","البسط يصبح 4n، فنقسم على n: 4/(√(1+4/n)+1).","عند n→∞ تصبح النهاية 4/(1+1)=2."],answer:"2",check:"المقام بعد القسمة على n يؤول إلى 2."},
    {id:"der-003",topic:"الاشتقاق",unit:"الاشتقاق",lesson:"معادلة المماس",level:"أساسي",question:"أوجد معادلة مماس منحنى f(x)=x² عند النقطة ذات الفاصلة 2.",keyIdea:"ميل المماس f′(a)، ويمر بالنقطة (a,f(a)).",steps:["نشتق: f′(x)=2x، ومنه f′(2)=4.","إحداثيا نقطة التماس هما (2,4).","معادلة المماس y−4=4(x−2)، أي y=4x−4."],answer:"y=4x−4",check:"يمر المستقيم بالنقطة (2,4) وميله 4."},
    {id:"der-004",topic:"الاشتقاق",unit:"الاشتقاق",lesson:"دراسة اتجاه التغير",level:"متوسط",question:"ادرس اتجاه تغير f(x)=x²−4x+1 على R.",keyIdea:"إشارة المشتقة تحدد اتجاه تغير التابع.",steps:["نحسب f′(x)=2x−4=2(x−2).","تكون المشتقة سالبة إذا x<2 وموجبة إذا x>2.","إذن f متناقص على ]−∞,2] ومتزايد على [2,+∞[."],answer:"قيمة صغرى عند x=2 وتساوي f(2)=−3.",check:"تتغير إشارة المشتقة من السالب إلى الموجب عند 2."},
    {id:"der-005",topic:"الاشتقاق",unit:"الاشتقاق",lesson:"اشتقاق جداء تابعين",level:"متقدم",question:"اشتق f(x)=(x²+1)eˣ.",keyIdea:"مشتقة الجداء u·v هي u′v+uv′.",steps:["نضع u=x²+1 وv=eˣ، فنحصل على u′=2x وv′=eˣ.","f′(x)=2xeˣ+(x²+1)eˣ.","نأخذ eˣ عاملاً مشتركاً: f′(x)=eˣ(x²+2x+1)."],answer:"f′(x)=eˣ(x+1)²",check:"بتطبيق قاعدة الجداء ثم تحليل x²+2x+1."},
    {id:"log-003",topic:"التابع اللوغاريتمي",unit:"التابع اللوغاريتمي النيبيري",lesson:"اشتقاق اللوغاريتم",level:"متوسط",question:"اشتق f(x)=ln(x²+1).",keyIdea:"مشتقة ln(u) هي u′/u عندما u موجب.",steps:["نضع u=x²+1، ونلاحظ أنه موجب لكل x.","مشتقة u هي 2x.","إذن f′(x)=2x/(x²+1)."],answer:"f′(x)=2x/(x²+1)",check:"المقام موجب دائماً، ومجال التعريف هو R."},
    {id:"log-004",topic:"التابع اللوغاريتمي",unit:"التابع اللوغاريتمي النيبيري",lesson:"حل معادلة لوغاريتمية",level:"متقدم",question:"حل المعادلة ln(x−1)=0.",keyIdea:"نحدد المجال أولاً ثم نستعمل أن ln(a)=0 يكافئ a=1.",steps:["شرط التعريف x−1>0، أي x>1.","من ln(x−1)=0 نستنتج x−1=e⁰=1.","إذن x=2، وهو يحقق شرط المجال."],answer:"مجموعة الحل {2}.",check:"ln(2−1)=ln(1)=0."},
    {id:"exp-003",topic:"التابع الأسي",unit:"التابع الأسي",lesson:"اشتقاق التابع الأسي المركب",level:"متوسط",question:"اشتق f(x)=e^(3x−2).",keyIdea:"مشتقة e^u هي u′e^u.",steps:["نضع u=3x−2، فتكون u′=3.","نطبق قاعدة اشتقاق المركب.","نحصل على f′(x)=3e^(3x−2)."],answer:"f′(x)=3e^(3x−2)",check:"العامل 3 هو مشتقة الأس الداخلي."},
    {id:"exp-004",topic:"التابع الأسي",unit:"التابع الأسي",lesson:"حل معادلة أسية",level:"أساسي",question:"حل المعادلة eˣ=5.",keyIdea:"نطبق اللوغاريتم الطبيعي على طرفي المعادلة لأن الدالة الأسية موجبة وتقابلية.",steps:["من eˣ=5 نأخذ ln الطرفين.","نستعمل ln(eˣ)=x.","إذن x=ln(5)."],answer:"x=ln(5)",check:"e^(ln 5)=5."},
    {id:"int-003",topic:"التكامل والتابع الأصلي",unit:"التكامل والتوابع الأصلية",lesson:"التكامل بالتجزئة",level:"متقدم",question:"احسب التكامل غير المحدد ∫x eˣ dx.",keyIdea:"نستعمل التكامل بالتجزئة باختيار u=x و dv=eˣ dx.",steps:["نختار u=x و dv=eˣ dx، فيكون du=dx وv=eˣ.","∫x eˣ dx=xeˣ−∫eˣ dx.","إذن النتيجة xeˣ−eˣ+C."],answer:"eˣ(x−1)+C",check:"اشتقاق eˣ(x−1) يعطي xeˣ."},
    {id:"int-004",topic:"التكامل والتابع الأصلي",unit:"التكامل والتوابع الأصلية",lesson:"المساحة باستعمال التكامل",level:"متوسط",question:"احسب مساحة الحيز المحصور بين منحنى y=2x ومحور الفواصل والمستقيمين x=0 وx=3.",keyIdea:"بما أن 2x غير سالب على [0,3] فالمساحة تساوي التكامل المحدد.",steps:["نكتب A=∫₀³2x dx.","تابع أصلي هو x².","A=3²−0²=9."],answer:"9 وحدات مربعة.",check:"المنحنى فوق محور الفواصل على المجال المحدد."},
    {id:"vec-002",topic:"الأشعة في الفراغ",unit:"الأشعة في الفراغ",lesson:"منتصف قطعة في الفراغ",level:"أساسي",question:"أوجد إحداثيات منتصف القطعة [AB] حيث A(−2,1,4) وB(4,3,−2).",keyIdea:"إحداثيات المنتصف هي متوسط إحداثيات طرفي القطعة في كل محور.",steps:["الإحداثي الأول: (−2+4)/2=1.","الثاني: (1+3)/2=2.","الثالث: (4−2)/2=1."],answer:"M(1,2,1)",check:"الشعاعان AM وMB متساويان في المركبات."},
    {id:"dot-002",topic:"الجداء السلمي في الفراغ",unit:"الجداء السلمي في الفراغ",lesson:"تعامد شعاعين",level:"أساسي",question:"تحقق من تعامد u=(1,2,−1) وv=(2,−1,0).",keyIdea:"يتعامد شعاعان غير معدومين إذا وفقط إذا كان جداؤهما السلمي صفراً.",steps:["نحسب u·v=1×2+2×(−1)+(−1)×0.","الناتج 2−2+0=0.","إذن الشعاعان متعامدان."],answer:"u ⟂ v",check:"الجداء السلمي يساوي صفراً."},
    {id:"dot-003",topic:"الجداء السلمي في الفراغ",unit:"الجداء السلمي في الفراغ",lesson:"زاوية شعاعين",level:"متقدم",question:"أوجد جيب تمام الزاوية بين u=(1,0,0) وv=(1,1,0).",keyIdea:"cos θ=(u·v)/(|u||v|).",steps:["الجداء السلمي u·v=1.","العياران |u|=1 و|v|=√2.","إذن cos θ=1/√2=√2/2."],answer:"θ=π/4",check:"الزاوية بين الشعاعين حادة، وجيب تمامها موجب."},
    {id:"line-002",topic:"المستقيمات والمستويات في الفراغ",unit:"المستقيمات والمستويات في الفراغ",lesson:"تمثيل وسيطي لمستقيم",level:"متوسط",question:"اكتب تمثيلاً وسيطياً للمستقيم المار بـ A(1,−2,0) وله شعاع توجيه u=(2,1,−1).",keyIdea:"نكتب إحداثيات نقطة عامة على المستقيم على صورة A+t u.",steps:["نكتب (x,y,z)=(1,−2,0)+t(2,1,−1).","بمقارنة المركبات نحصل على x=1+2t.","وكذلك y=−2+t و z=−t، حيث t∈R."],answer:"x=1+2t، y=−2+t، z=−t.",check:"عند t=0 نحصل على النقطة A، واتجاه التغير هو u."},
    {id:"cx-003",topic:"الأعداد العقدية",unit:"الأعداد العقدية",lesson:"مرافق عدد عقدي",level:"أساسي",question:"أوجد مرافق z=−3+2i واحسب z·z̄.",keyIdea:"مرافق a+bi هو a−bi، وجداؤه بالعدد الأصلي يساوي مربع العيار.",steps:["المرافق هو z̄=−3−2i.","نحسب z·z̄=(−3+2i)(−3−2i).","باستعمال فرق مربعين نحصل على 9+4=13."],answer:"z̄=−3−2i و z·z̄=13",check:"الجداء عدد حقيقي موجب يساوي |z|²."},
    {id:"cx-004",topic:"الأعداد العقدية",unit:"الأعداد العقدية",lesson:"حل معادلة من الدرجة الثانية في C",level:"متوسط",question:"حل في C المعادلة z²+1=0.",keyIdea:"نستعمل i²=−1 ونبحث عن جذري العدد −1 في مجموعة الأعداد العقدية.",steps:["ننقل 1: z²=−1.","بما أن i²=−1 فإن i حل، وكذلك −i.","إذن الحلّان z=i أو z=−i."],answer:"S={i,−i}",check:"مربع كل من i و−i يساوي −1."},
    {id:"complex-geometry-002",topic:"تطبيقات الأعداد العقدية",unit:"تطبيقات الأعداد العقدية في الهندسة",lesson:"التماثل المركزي",level:"أساسي",question:"ما لاحقة صورة النقطة ذات اللاحقة z=3−2i بالتماثل المركزي مركزه المبدأ؟",keyIdea:"التماثل المركزي مركزه المبدأ يحول اللاحقة z إلى −z.",steps:["نستعمل العلاقة z′=−z.","نعوّض z=3−2i فنحصل على z′=−(3−2i).","نفتح القوس: z′=−3+2i."],answer:"z′=−3+2i",check:"النقطتان متقابلتان بالنسبة إلى المبدأ."},
    {id:"comb-002",topic:"التحليل التوافقي",unit:"التحليل التوافقي",lesson:"الترتيبات",level:"متوسط",question:"بكم طريقة يمكن اختيار رئيس ونائب من بين 6 طلاب مختلفين؟",keyIdea:"المنصبان مختلفان، لذا يهم ترتيب الاختيار ونستعمل الترتيبات.",steps:["نختار الرئيس بـ6 طرق.","بعد اختياره يبقى 5 خيارات للنائب.","عدد الطرق 6×5=30."],answer:"30 طريقة.",check:"تبديل الشخصين بين المنصبين يعطي اختياراً مختلفاً."},
    {id:"comb-003",topic:"التحليل التوافقي",unit:"التحليل التوافقي",lesson:"مفكوك ثنائي الحدين",level:"متقدم",question:"أوجد معامل x² في مفكوك (1+x)⁵.",keyIdea:"معامل xᵏ في (1+x)ⁿ هو التوافيق C(n,k).",steps:["المعامل المطلوب هو C(5,2).","نحسب C(5,2)=5!/(2!3!).","الناتج (5×4)/2=10."],answer:"10",check:"الحد الذي يحوي x² هو 10x²."},
    {id:"prob-003",topic:"الاحتمالات",unit:"الاحتمالات",lesson:"استقلال حادثتين",level:"متوسط",question:"إذا كان P(A)=0.4 وP(B)=0.5 والحادثتان مستقلتين، احسب P(A∩B).",keyIdea:"عند استقلال حادثتين يكون احتمال تقاطعهما حاصل ضرب احتماليهما.",steps:["نكتب P(A∩B)=P(A)P(B).","نعوّض 0.4×0.5.","الناتج 0.2."],answer:"P(A∩B)=0.2",check:"الاحتمال الناتج يقع بين 0 و1."},
    {id:"prob-004",topic:"الاحتمالات",unit:"الاحتمالات",lesson:"قانون الاحتمال الكلي",level:"متقدم",question:"يشكل A وĀ تجزئة للفضاء، حيث P(A)=0.3 وP(B|A)=0.8 وP(B|Ā)=0.2. احسب P(B).",keyIdea:"نطبق قانون الاحتمال الكلي على التجزئة {A,Ā}.",steps:["نكتب P(B)=P(A)P(B|A)+P(Ā)P(B|Ā).","لدينا P(Ā)=1−0.3=0.7.","إذن P(B)=0.3×0.8+0.7×0.2=0.38."],answer:"P(B)=0.38",check:"احتمالا A وĀ مجموعهما 1، والنتيجة بين 0 و1."}

    ,
    {id:"seq-006",topic:"المتتاليات",unit:"المتتاليات",lesson:"تحديد أساس متتالية حسابية",level:"أساسي",question:"متتالية حسابية تحقق u₃=11 وu₇=27. أوجد أساسها وحدها الأول.",keyIdea:"نستعمل uₙ=u₁+(n−1)r، ثم نطرح العلاقتين لإزالة u₁.",steps:["لدينا u₇−u₃=(7−3)r، أي 27−11=4r، ومنه r=4.","نعوض في u₃=u₁+2r فنجد 11=u₁+8.","إذن u₁=3 والأساس r=4."],answer:"u₁=3 و r=4",check:"الحد الثالث 3+8=11، والحد السابع 3+24=27."},
    {id:"seq-007",topic:"المتتاليات",unit:"المتتاليات",lesson:"مجموع حدود متتالية هندسية",level:"متوسط",question:"احسب مجموع الحدود الخمسة الأولى للمتتالية الهندسية التي حدها الأول 2 وأساسها 3.",keyIdea:"عندما q≠1، مجموع أول n حدود هندسية هو u₁(1−qⁿ)/(1−q).",steps:["نعوض u₁=2 وq=3 وn=5.","S₅=2(1−3⁵)/(1−3).","بما أن 3⁵=243، نحصل على S₅=2×242/2=242."],answer:"242",check:"الحدود هي 2 و6 و18 و54 و162، ومجموعها 242."},
    {id:"lim-006",topic:"النهايات والاستمرار",unit:"التوابع والنهايات والاستمرار",lesson:"نهاية كسرية عند اللانهاية",level:"أساسي",question:"احسب نهاية (3x²−x+1)/(x²+4) عندما x يؤول إلى ما لا نهاية.",keyIdea:"في كسر كثيرتي حدود من الدرجة نفسها، النهاية هي نسبة معاملي الحدين الأعلى درجة.",steps:["نقسم البسط والمقام على x².","تصبح العبارة (3−1/x+1/x²)/(1+4/x²).","عند x→∞ تختفي الحدود التي تتضمن 1/x، فتكون النهاية 3."],answer:"3",check:"الحدان المسيطران هما 3x² وx²."},
    {id:"lim-007",topic:"النهايات والاستمرار",unit:"التوابع والنهايات والاستمرار",lesson:"المقارب العمودي",level:"متوسط",question:"ادرس وجود مقارب عمودي للتابع f(x)=1/(x−2) عند x=2.",keyIdea:"يكون المستقيم x=a مقارباً عمودياً إذا كانت إحدى النهايتين الجانبيتين غير منتهية.",steps:["عندما x→2⁺ يكون x−2 موجباً ويقترب من الصفر، لذلك f(x)→+∞.","عندما x→2⁻ يكون x−2 سالباً ويقترب من الصفر، لذلك f(x)→−∞.","إذن المستقيم x=2 مقارب عمودي."],answer:"المقارب العمودي هو x=2.",check:"تتباعد قيم التابع عند الاقتراب من 2 من الجهتين."},
    {id:"seq-limit-004",topic:"نهاية متتالية",unit:"نهاية المتتالية",lesson:"نهاية متتالية كسرية",level:"أساسي",question:"احسب نهاية uₙ=(4n²−n+2)/(2n²+3) عندما n→∞.",keyIdea:"نقسم البسط والمقام على أعلى قوة لـ n في المقام.",steps:["نقسم على n² فنحصل على (4−1/n+2/n²)/(2+3/n²).","عندما n→∞ تؤول 1/n و1/n² إلى الصفر.","النهاية تساوي 4/2=2."],answer:"2",check:"نسبة معاملي الحدين من الدرجة الثانية هي 4/2."},
    {id:"seq-limit-005",topic:"نهاية متتالية",unit:"نهاية المتتالية",lesson:"مقارنة متتاليتين",level:"متوسط",question:"إذا كان 0≤uₙ≤1/n لكل n≥1، استنتج نهاية uₙ.",keyIdea:"نطبق مبرهنة الحصر بعد معرفة نهاية الحدين الحاصرين.",steps:["لدينا 1/n→0 و0→0 عندما n→∞.","وبحسب المعطى تقع uₙ بين هاتين المتتاليتين.","إذن، بمبرهنة الحصر، uₙ→0."],answer:"نهاية uₙ تساوي 0.",check:"المتتالية محصورة بين متتاليتين لهما النهاية نفسها."},
    {id:"der-006",topic:"الاشتقاق",unit:"الاشتقاق",lesson:"القيم الحدية المحلية",level:"متوسط",question:"حدد القيم الحدية المحلية للتابع f(x)=x³−3x.",keyIdea:"نحل f′(x)=0 ثم ندرس تغير إشارة المشتقة.",steps:["f′(x)=3x²−3=3(x−1)(x+1)، والنقط الحرجة −1 و1.","إشارة المشتقة موجبة خارج المجال [−1,1] وسالبة داخله.","يتغير التابع من تزايد إلى تناقص عند −1، ومن تناقص إلى تزايد عند 1."],answer:"قيمة عظمى محلية f(−1)=2، وقيمة صغرى محلية f(1)=−2.",check:"قيمتا المشتقة تتغيران بالإشارتين المناسبتين حول النقطتين."},
    {id:"der-007",topic:"الاشتقاق",unit:"الاشتقاق",lesson:"مشتقة خارج قسمة",level:"متقدم",question:"اشتق f(x)=(x+1)/(x−1) على مجال تعريفها.",keyIdea:"مشتقة u/v هي (u′v−uv′)/v² عندما v غير معدوم.",steps:["مجال التعريف هو R\\{1}. نضع u=x+1 وv=x−1، ومنه u′=v′=1.","f′(x)=[(x−1)−(x+1)]/(x−1)².","نبسط البسط فنحصل على −2."],answer:"f′(x)=−2/(x−1)²، حيث x≠1.",check:"المشتقة سالبة على مجال التعريف، وهو ما ينسجم مع تناقص التابع على كل من مجاليه."},
    {id:"log-005",topic:"التابع اللوغاريتمي",unit:"التابع اللوغاريتمي النيبيري",lesson:"خواص اللوغاريتم وحساب القيم",level:"أساسي",question:"بسط ln(12)−ln(3)+ln(2).",keyIdea:"نستعمل ln(a)−ln(b)=ln(a/b) وln(a)+ln(b)=ln(ab) للأعداد الموجبة.",steps:["ln(12)−ln(3)=ln(12/3)=ln(4).","ثم ln(4)+ln(2)=ln(4×2).","إذن العبارة تساوي ln(8)."],answer:"ln(8)",check:"جميع الأعداد داخل اللوغاريتم موجبة، وقواعد الجمع والطرح مطبقة."},
    {id:"log-006",topic:"التابع اللوغاريتمي",unit:"التابع اللوغاريتمي النيبيري",lesson:"حل متراجحة لوغاريتمية",level:"متقدم",question:"حل المتراجحة ln(x)>ln(3).",keyIdea:"اللوغاريتم النيبيري متزايد تماماً على المجال ]0,+∞[.",steps:["شرط التعريف x>0.","بما أن ln متزايد، فإن ln(x)>ln(3) يكافئ x>3.","الحل يحقق تلقائياً شرط التعريف."],answer:"مجموعة الحل ]3,+∞[.",check:"كل x أكبر من 3 يعطي ln(x) أكبر من ln(3)."},
    {id:"exp-005",topic:"التابع الأسي",unit:"التابع الأسي",lesson:"خواص القوى الأسية",level:"أساسي",question:"بسط e^(2x)×e^(3−x) واكتب الناتج على صورة أسية واحدة.",keyIdea:"عند ضرب قوتين لهما الأساس نفسه نجمع الأسين.",steps:["نجمع الأسين: 2x+(3−x)=x+3.","إذن حاصل الضرب يساوي e^(x+3).","ويمكن كتابته أيضاً e³eˣ."],answer:"e^(x+3)",check:"بتوسيع e^(x+3)=eˣe³ نحصل على حاصل الضرب نفسه."},
    {id:"exp-006",topic:"التابع الأسي",unit:"التابع الأسي",lesson:"دراسة تغير تابع أسي",level:"متوسط",question:"ادرس اتجاه تغير f(x)=e^(−2x) على R.",keyIdea:"نحدد إشارة المشتقة، مع العلم أن e^u موجب لكل u حقيقي.",steps:["نشتق باستعمال قاعدة التابع المركب: f′(x)=−2e^(−2x).","بما أن e^(−2x)>0 فإن f′(x)<0 لكل x.","إذن f متناقص تماماً على R."],answer:"f متناقص تماماً على R.",check:"إشارة المشتقة سالبة على كامل مجموعة التعريف."},
    {id:"int-005",topic:"التكامل والتابع الأصلي",unit:"التكامل والتوابع الأصلية",lesson:"تابع أصلي لقوة كثيرة حدود",level:"أساسي",question:"أوجد جميع التوابع الأصلية للتابع f(x)=3x²−4x+2.",keyIdea:"نكامل حدّاً حدّاً، مع إضافة ثابت التكامل.",steps:["تابع أصلي لـ3x² هو x³.","تابع أصلي لـ−4x هو −2x²، ولقوة 2 هو 2x.","إذن F(x)=x³−2x²+2x+C."],answer:"F(x)=x³−2x²+2x+C، حيث C ثابت حقيقي.",check:"اشتقاق F يعيد 3x²−4x+2."},
    {id:"int-006",topic:"التكامل والتابع الأصلي",unit:"التكامل والتوابع الأصلية",lesson:"خاصية خطية التكامل المحدد",level:"متوسط",question:"احسب ∫₀²(3x²+1) dx.",keyIdea:"نوجد تابعاً أصلياً ثم نحسب فرق قيمتيه عند حدي التكامل.",steps:["تابع أصلي هو F(x)=x³+x.","نحسب F(2)=8+2=10 وF(0)=0.","قيمة التكامل هي F(2)−F(0)=10."],answer:"10",check:"المكاملة موجبة لأن integrand 3x²+1 موجب على [0,2]."},
    {id:"vec-003",topic:"الأشعة في الفراغ",unit:"الأشعة في الفراغ",lesson:"استقامية ثلاث نقاط",level:"متوسط",question:"تحقق من استقامية A(1,0,2) وB(3,1,0) وC(5,2,−2).",keyIdea:"تكون النقاط مستقيمية إذا كان الشعاعان AB وAC متناسبين.",steps:["نحسب AB=(2,1,−2).","ونحسب AC=(4,2,−4).","نلاحظ أن AC=2AB، إذن الشعاعان متوازيان والنقاط مستقيمية."],answer:"النقاط A وB وC مستقيمية.",check:"مركبات AC تساوي ضعف مركبات AB."},
    {id:"dot-004",topic:"الجداء السلمي في الفراغ",unit:"الجداء السلمي في الفراغ",lesson:"حساب زاوية باستعمال الجداء السلمي",level:"متقدم",question:"احسب جيب تمام الزاوية بين u=(1,1,0) وv=(1,0,1).",keyIdea:"نقسم الجداء السلمي على حاصل ضرب طولي الشعاعين.",steps:["u·v=1×1+1×0+0×1=1.","لدينا |u|=√2 و|v|=√2.","إذن cos θ=1/(√2×√2)=1/2."],answer:"cos θ=1/2، ومنه θ=π/3.",check:"الزاوية بين الشعاعين غير منفرجة لأن الجداء السلمي موجب."},
    {id:"line-003",topic:"المستقيمات والمستويات في الفراغ",unit:"المستقيمات والمستويات في الفراغ",lesson:"توازي مستويين",level:"متوسط",question:"حدد العلاقة بين المستويين 2x−y+z=1 و4x−2y+2z=5.",keyIdea:"إذا كان شعاعا الناظم متناسبين فالمستويان متوازيان أو منطبقان، ثم نقارن الثابتين.",steps:["شعاعا الناظم هما (2,−1,1) و(4,−2,2)، والثاني ضعف الأول.","لو كان المستويان منطبقين لكان الطرف الأيمن في المعادلة الثانية ضعف 1، أي 2.","لكن الثابت هو 5، إذن المستويان مختلفان ومتوازيان."],answer:"المستويان متوازيان ومتمايزان.",check:"الناظمان متناسبان، والمعادلتان غير متكافئتين."},
    {id:"cx-005",topic:"الأعداد العقدية",unit:"الأعداد العقدية",lesson:"حل معادلة عقدية من الشكل z²=a",level:"متوسط",question:"حل في C المعادلة z²=−4.",keyIdea:"نستعمل i²=−1 ونبحث عن العددين اللذين مربعهما −4.",steps:["نكتب −4=4(−1)=4i².","إذن z²=(2i)².","ومن ثم z=2i أو z=−2i."],answer:"S={2i,−2i}",check:"مربع كل من 2i و−2i يساوي −4."},
    {id:"cx-006",topic:"الأعداد العقدية",unit:"الأعداد العقدية",lesson:"حلقة العدد العقدي",level:"متقدم",question:"اكتب z=(1+i)/(1−i) على الشكل الجبري a+bi.",keyIdea:"نضرب البسط والمقام بمرافق المقام لجعل المقام حقيقياً.",steps:["نضرب في (1+i)/(1+i)، فنحصل على (1+i)²/(1−i²).","البسط 1+2i+i²=2i، والمقام 1−(−1)=2.","إذن z=2i/2=i."],answer:"z=i",check:"نضرب i في (1−i) فنحصل على 1+i."},
    {id:"complex-geometry-003",topic:"تطبيقات الأعداد العقدية",unit:"تطبيقات الأعداد العقدية في الهندسة",lesson:"الانسحاب في المستوي العقدي",level:"متوسط",question:"صورة النقطة ذات اللاحقة z=2−i بالانسحاب ذي الشعاع الذي لاحقته a=−1+3i؛ أوجد لاحقة الصورة.",keyIdea:"في الانسحاب ذي الشعاع ذي اللاحقة a، تكون لاحقة الصورة z′=z+a.",steps:["نستعمل العلاقة z′=z+a.","نعوض z=2−i وa=−1+3i.","نجمع الجزأين الحقيقي والتخيلي: z′=1+2i."],answer:"z′=1+2i",check:"فرق اللاحقتين z′−z يساوي −1+3i، وهو لاحقة شعاع الانسحاب."},
    {id:"comb-004",topic:"التحليل التوافقي",unit:"التحليل التوافقي",lesson:"اختيار لجنة",level:"أساسي",question:"كم لجنة من 3 طلاب يمكن تشكيلها من مجموعة تضم 7 طلاب؟",keyIdea:"ترتيب اختيار أعضاء اللجنة لا يهم، لذا نستعمل التوافيق.",steps:["عدد اللجان هو C(7,3).","نحسب C(7,3)=7!/(3!4!).","الناتج (7×6×5)/(3×2×1)=35."],answer:"35 لجنة.",check:"لا نميز بين ترتيبين للأشخاص الثلاثة في اللجنة نفسها."},
    {id:"comb-005",topic:"التحليل التوافقي",unit:"التحليل التوافقي",lesson:"عدد كلمات من أحرف مختلفة",level:"متوسط",question:"كم ترتيباً مختلفاً يمكن تكوينه من الأحرف الأربعة A وB وC وD باستعمالها جميعاً مرة واحدة؟",keyIdea:"ترتيب جميع العناصر المختلفة وعددها n يساوي n!.",steps:["للموضع الأول 4 اختيارات.","للموضع الثاني 3، ثم 2 للثالث، و1 للرابع.","العدد الكلي 4×3×2×1=24."],answer:"24 ترتيباً.",check:"هذا يساوي 4!."},
    {id:"prob-005",topic:"الاحتمالات",unit:"الاحتمالات",lesson:"احتمال المتممة",level:"أساسي",question:"إذا كان احتمال وقوع الحادثة A يساوي 0.35، احسب احتمال عدم وقوعها.",keyIdea:"احتمال الحادثة المتممة هو 1 ناقص احتمال الحادثة.",steps:["نرمز للمتممة بـ Ā.","نستعمل P(Ā)=1−P(A).","إذن P(Ā)=1−0.35=0.65."],answer:"0.65",check:"مجموع احتمالي الحادثة ومتممتها يساوي 1."},
    {id:"prob-006",topic:"الاحتمالات",unit:"الاحتمالات",lesson:"احتمال اتحاد حادثتين متنافيتين",level:"متوسط",question:"حادثتان A وB متنافيتان، واحتمالهما 0.2 و0.45. احسب P(A∪B).",keyIdea:"عند تنافي حادثتين يكون احتمال اتحادهما مجموع احتماليهما.",steps:["نكتب P(A∪B)=P(A)+P(B) لأن P(A∩B)=0.","نعوض 0.2+0.45.","الناتج 0.65."],answer:"P(A∪B)=0.65",check:"الاحتمال لا يتجاوز 1، والحدثان لا يقعان معاً."},
    {id:"prob-007",topic:"الاحتمالات",unit:"الاحتمالات",lesson:"توزيع احتمال متغير عشوائي",level:"متقدم",question:"متغير عشوائي X يأخذ القيم 0 و1 و2 باحتمالات 0.2 و0.5 و0.3 على الترتيب. احسب الأمل الرياضي E(X).",keyIdea:"الأمل الرياضي لمتغير عشوائي متقطع هو مجموع جداءات كل قيمة باحتمالها.",steps:["نكتب E(X)=0×0.2+1×0.5+2×0.3.","نحسب الحدود: 0+0.5+0.6.","إذن E(X)=1.1."],answer:"1.1",check:"الاحتمالات 0.2+0.5+0.3 مجموعها 1."}

    ,
    {id:"lim-008",topic:"النهايات والاستمرار",unit:"التوابع والنهايات والاستمرار",lesson:"الاستمرار عند نقطة",level:"أساسي",question:"حدد قيمة a التي تجعل f(x)=(x²−1)/(x−1) إذا x≠1 وf(1)=a تابعاً مستمراً عند x=1.",keyIdea:"نفرض قيمة التابع عند النقطة مساوية لنهايته عندما تقترب x من تلك النقطة.",steps:["نحلل x²−1=(x−1)(x+1)، ومنه f(x)=x+1 عندما x≠1.","نحسب النهاية عند 1: lim f(x)=1+1=2.","شرط الاستمرار هو a=f(1)=lim f(x)، لذلك a=2."],answer:"a=2",check:"عند اختيار a=2 تتساوى قيمة التابع مع نهايته عند x=1."},
    {id:"lim-009",topic:"النهايات والاستمرار",unit:"التوابع والنهايات والاستمرار",lesson:"نهاية باستعمال المرافق",level:"متوسط",question:"احسب lim عندما x→0 للتعبير (√(x+4)−2)/x.",keyIdea:"نضرب بالمرافق لإزالة حالة عدم التعيين من النوع 0/0.",steps:["نضرب البسط والمقام بـ(√(x+4)+2).","يصبح البسط (x+4)−4=x، فنختزل x مع المقام عندما x≠0.","يتبقى 1/(√(x+4)+2)، ونهايته عند الصفر تساوي 1/4."],answer:"1/4",check:"بالتعويض في التعبير المختزل نحصل على 1/(2+2)=1/4."},
    {id:"seq-008",topic:"المتتاليات",unit:"المتتاليات",lesson:"رتابة متتالية حسابية",level:"أساسي",question:"ادرس رتابة المتتالية الحسابية التي حدها الأول u₁=7 وأساسها r=−3.",keyIdea:"إشارة أساس المتتالية الحسابية تحدد رتابتها.",steps:["نكتب uₙ₊₁−uₙ=r.","بما أن r=−3<0 فإن uₙ₊₁−uₙ<0 لكل n.","إذن المتتالية متناقصة تماماً."],answer:"المتتالية متناقصة تماماً.",check:"كل حد يقل عن الحد السابق بمقدار 3."},
    {id:"seq-009",topic:"المتتاليات",unit:"المتتاليات",lesson:"تحديد أساس متتالية هندسية",level:"متوسط",question:"متتالية هندسية حدودها موجبة وتحقق u₂=6 وu₅=162. أوجد أساسها الموجب.",keyIdea:"في المتتالية الهندسية u₅=u₂q³، ونستعمل شرط إيجابية الأساس.",steps:["نكتب 162=6q³، ومنه q³=27.","نأخذ الجذر التكعيبي فنجد q=3.","الأساس موجب كما يوافق المعطى."],answer:"q=3",check:"6×3³=6×27=162."},
    {id:"seq-limit-006",topic:"نهاية متتالية",unit:"نهاية المتتالية",lesson:"نهاية متتالية هندسية",level:"أساسي",question:"احسب نهاية uₙ=(1/3)ⁿ عندما n→∞.",keyIdea:"إذا كان أساس المتتالية الهندسية محصوراً بين −1 و1 فإن قوى هذا الأساس تؤول إلى الصفر.",steps:["لدينا uₙ=qⁿ حيث q=1/3.","نلاحظ أن |q|=1/3<1.","إذن lim qⁿ=0 عندما n→∞."],answer:"نهاية uₙ تساوي 0.",check:"كلما ازداد n صغرت قيمة (1/3)ⁿ واقتربت من الصفر."},
    {id:"seq-limit-007",topic:"نهاية متتالية",unit:"نهاية المتتالية",lesson:"نهاية متتالية معرفة بعلاقة رجعية",level:"متوسط",question:"لتكن uₙ=2+1/n لكل n≥1. احسب نهايتها وبيّن أنها أكبر من 2.",keyIdea:"نفصل الحد الثابت عن الحد الذي يؤول إلى الصفر.",steps:["لدينا uₙ=2+1/n.","بما أن 1/n>0 لكل n≥1 فإن uₙ>2.","وبما أن 1/n→0 فإن uₙ→2."],answer:"lim uₙ=2، مع uₙ>2 لكل n.",check:"الفرق uₙ−2=1/n موجب ويؤول إلى الصفر."},
    {id:"der-008",topic:"الاشتقاق",unit:"الاشتقاق",lesson:"مشتقة جداء تابعين",level:"أساسي",question:"اشتق f(x)=(x²+1)eˣ.",keyIdea:"مشتقة جداء تابعين هي u′v+uv′.",steps:["نضع u=x²+1 وv=eˣ، فنجد u′=2x وv′=eˣ.","نطبق قاعدة الجداء: f′(x)=2xeˣ+(x²+1)eˣ.","نأخذ eˣ عاملاً مشتركاً."],answer:"f′(x)=eˣ(x²+2x+1)=eˣ(x+1)²",check:"بتوسيع الصيغة الأخيرة نحصل على eˣ(x²+2x+1)، المطابقة لقاعدة الجداء."},
    {id:"der-009",topic:"الاشتقاق",unit:"الاشتقاق",lesson:"مشتقة تابع مركب",level:"متوسط",question:"اشتق f(x)=(3x−2)⁵.",keyIdea:"نستعمل قاعدة مشتقة قوة تابع مركب: (uⁿ)′=n uⁿ⁻¹u′.",steps:["نضع u=3x−2، ومنه u′=3.","نطبق القاعدة: f′(x)=5(3x−2)⁴×3.","نضرب الثابتين 5 و3."],answer:"f′(x)=15(3x−2)⁴",check:"العامل 3 ناتج عن مشتقة التعبير الداخلي 3x−2."},
    {id:"log-007",topic:"التابع اللوغاريتمي",unit:"التابع اللوغاريتمي النيبيري",lesson:"حل معادلة لوغاريتمية",level:"متوسط",question:"حل المعادلة ln(x−1)=0.",keyIdea:"نستخدم أن ln(t)=0 يكافئ t=1 مع مراعاة شرط التعريف.",steps:["شرط التعريف x−1>0، أي x>1.","من ln(x−1)=0 نستنتج x−1=e⁰=1.","إذن x=2، وهو يحقق شرط التعريف."],answer:"مجموعة الحل S={2}.",check:"ln(2−1)=ln(1)=0."},
    {id:"log-008",topic:"التابع اللوغاريتمي",unit:"التابع اللوغاريتمي النيبيري",lesson:"مشتقة اللوغاريتم النيبيري",level:"أساسي",question:"أوجد مشتقة f(x)=ln(2x+5) وحدد مجالها.",keyIdea:"مشتقة ln(u) هي u′/u بشرط u>0.",steps:["شرط التعريف 2x+5>0، أي x>−5/2.","نضع u=2x+5، ومنه u′=2.","إذن f′(x)=2/(2x+5) على مجال التعريف."],answer:"D=]−5/2,+∞[ و f′(x)=2/(2x+5).",check:"المقام موجب على المجال المحدد، والمشتقة معرفة عليه."},
    {id:"exp-007",topic:"التابع الأسي",unit:"التابع الأسي",lesson:"حل معادلة أسية",level:"أساسي",question:"حل المعادلة e^(2x−1)=e⁵.",keyIdea:"التابع الأسي تقابلي، لذلك تتساوى الأسس عندما تتساوى القيم.",steps:["بما أن eˣ متزايد تماماً، فإن 2x−1=5.","نضيف 1 إلى الطرفين فنحصل على 2x=6.","نقسم على 2 فنجد x=3."],answer:"S={3}",check:"عند x=3 يصبح الأس 2×3−1=5."},
    {id:"exp-008",topic:"التابع الأسي",unit:"التابع الأسي",lesson:"مشتقة تابع أسي مركب",level:"متوسط",question:"اشتق f(x)=e^(x²−3x).",keyIdea:"مشتقة eᵘ هي u′eᵘ.",steps:["نضع u=x²−3x، ومنه u′=2x−3.","نطبق قاعدة مشتقة التابع الأسي المركب.","نحصل على f′(x)=(2x−3)e^(x²−3x)."],answer:"f′(x)=(2x−3)e^(x²−3x)",check:"مشتقة الأس x²−3x هي 2x−3، وهو العامل المضروب أمام الأسية."},
    {id:"int-007",topic:"التكامل والتابع الأصلي",unit:"التكامل والتوابع الأصلية",lesson:"التكامل بالتبديل البسيط",level:"متوسط",question:"احسب ∫₂⁴ 2x(x²+1)³ dx.",keyIdea:"نستعمل التبديل u=x²+1 بحيث du=2x dx.",steps:["نضع u=x²+1، وعند x=2 يكون u=5 وعند x=4 يكون u=17.","يتحول التكامل إلى ∫₅¹⁷ u³ du.","نحسب [u⁴/4]₅¹⁷=(17⁴−5⁴)/4."],answer:"(17⁴−5⁴)/4=20724",check:"مشتقة (x²+1)⁴/4 هي 2x(x²+1)³، والتعويض عند الحدين يعطي النتيجة نفسها."},
    {id:"int-008",topic:"التكامل والتابع الأصلي",unit:"التكامل والتوابع الأصلية",lesson:"المساحة باستعمال التكامل",level:"متوسط",question:"احسب مساحة الحيز المحصور بين منحنى y=x والمستقيمين x=0 وx=3 ومحور الفواصل.",keyIdea:"عندما يكون التابع غير سالب على المجال، تساوي المساحة التكامل المحدد.",steps:["على [0,3] لدينا x≥0، لذا المساحة تساوي ∫₀³ x dx.","تابع أصلي لـx هو F(x)=x²/2.","المساحة F(3)−F(0)=9/2."],answer:"المساحة = 9/2 وحدة مربعة.",check:"المساحة مثلث قائم قاعدته 3 وارتفاعه 3، ومساحته (3×3)/2=9/2."},
    {id:"vec-004",topic:"الأشعة في الفراغ",unit:"الأشعة في الفراغ",lesson:"إحداثيات منتصف قطعة",level:"أساسي",question:"أوجد إحداثيات منتصف القطعة [AB] حيث A(−1,2,4) وB(3,0,−2).",keyIdea:"إحداثيات المنتصف هي متوسطا إحداثيات طرفي القطعة في كل محور.",steps:["إحداثي x للمنتصف هو (−1+3)/2=1.","إحداثي y هو (2+0)/2=1.","إحداثي z هو (4−2)/2=1."],answer:"I(1,1,1)",check:"الشعاعان AI وIB متساويان في الإحداثيات، فكل منهما (2,−1,−3)."},
    {id:"dot-005",topic:"الجداء السلمي في الفراغ",unit:"الجداء السلمي في الفراغ",lesson:"تعامد شعاعين",level:"أساسي",question:"تحقق من تعامد u=(1,2,−1) وv=(2,−1,0).",keyIdea:"شعاعان غير معدومين متعامدان إذا وفقط إذا كان جداؤهما السلمي صفراً.",steps:["نحسب u·v=1×2+2×(−1)+(−1)×0.","الناتج 2−2+0=0.","إذن الشعاعان متعامدان."],answer:"u·v=0، وبالتالي u⊥v.",check:"شرط التعامد بالجداء السلمي متحقق تماماً."},
    {id:"line-004",topic:"المستقيمات والمستويات في الفراغ",unit:"المستقيمات والمستويات في الفراغ",lesson:"معادلة مستوى من نقطة وناظم",level:"متوسط",question:"اكتب معادلة المستوى الذي يمر بالنقطة A(1,−2,3) وناظمه n=(2,1,−1).",keyIdea:"معادلة المستوى تحقق n·(X−A)=0.",steps:["نكتب 2(x−1)+(y+2)−(z−3)=0.","نفتح الأقواس: 2x−2+y+2−z+3=0.","نجمع الحدود الثابتة."],answer:"2x+y−z+3=0",check:"بتعويض A(1,−2,3) نحصل على 2−2−3+3=0."},
    {id:"cx-007",topic:"الأعداد العقدية",unit:"الأعداد العقدية",lesson:"مرافق عدد عقدي",level:"أساسي",question:"إذا كان z=−3+4i، أوجد مرافقه واحسب z×z̄.",keyIdea:"مرافق a+bi هو a−bi، وحاصل ضرب العدد بمرافقه يساوي مربّع معياره.",steps:["نغير إشارة الجزء التخيلي فنجد z̄=−3−4i.","نحسب z z̄=(−3+4i)(−3−4i).","باستعمال فرق مربعين نحصل على 9−(4i)²=9+16=25."],answer:"z̄=−3−4i و z z̄=25",check:"|z|²=(−3)²+4²=25."},
    {id:"cx-008",topic:"الأعداد العقدية",unit:"الأعداد العقدية",lesson:"معيار عدد عقدي",level:"متوسط",question:"احسب معيار العدد العقدي z=5−12i.",keyIdea:"معيار a+bi هو √(a²+b²).",steps:["الجزء الحقيقي a=5 والتخيلي b=−12.","نحسب |z|=√(5²+(−12)²).","إذن |z|=√(25+144)=√169."],answer:"|z|=13",check:"مربع المعيار 169 يساوي مجموع مربعي الجزأين الحقيقي والتخيلي."},
    {id:"complex-geometry-004",topic:"تطبيقات الأعداد العقدية",unit:"تطبيقات الأعداد العقدية في الهندسة",lesson:"الدوران مركزه المبدأ",level:"متقدم",question:"صورة النقطة ذات اللاحقة z=1+i بدوران مركزه المبدأ وزاويته π/2؛ أوجد لاحقة الصورة.",keyIdea:"الدوران مركزه المبدأ وزاويته θ يحول z إلى z′=e^(iθ)z.",steps:["عند θ=π/2 يكون e^(iθ)=i.","إذن z′=i(1+i)=i+i².","وبما أن i²=−1 نحصل على z′=−1+i."],answer:"z′=−1+i",check:"الضرب بـi يدير الشعاع ربع دورة موجبة ويحافظ على المعيار: |z′|=|z|=√2."},
    {id:"comb-006",topic:"التحليل التوافقي",unit:"التحليل التوافقي",lesson:"التوافيق مع شرط",level:"متوسط",question:"من بين 5 طلاب و4 طالبات، كم لجنة من شخصين يمكن تشكيلها بحيث تضم طالباً وطالبة؟",keyIdea:"نختار شخصاً واحداً من كل مجموعة مستقلة ثم نضرب عدد الاختيارات.",steps:["اختيار الطالب يتم بـ5 طرق.","اختيار الطالبة يتم بـ4 طرق.","بحسب مبدأ الضرب يكون العدد 5×4=20."],answer:"20 لجنة.",check:"كل لجنة مطلوبة تتحدد باختيار زوج واحد (طالب، طالبة) دون اعتبار للترتيب."},
    {id:"comb-007",topic:"التحليل التوافقي",unit:"التحليل التوافقي",lesson:"معامل حد في مفكوك ثنائي الحدين",level:"متقدم",question:"أوجد معامل x³ في مفكوك (2+x)⁵.",keyIdea:"نستعمل الحد العام C(n,k)a^(n−k)xᵏ في مفكوك (a+x)ⁿ.",steps:["الحد الذي يحوي x³ يقابل k=3.","معامله هو C(5,3)×2^(5−3).","نحسب 10×4=40."],answer:"معامل x³ هو 40.",check:"الحد المطلوب هو 40x³."},
    {id:"prob-008",topic:"الاحتمالات",unit:"الاحتمالات",lesson:"احتمال حادثتين مستقلتين ومتممتيهما",level:"متوسط",question:"حادثتان مستقلتان A وB تحققان P(A)=0.3 وP(B)=0.4. احسب احتمال عدم وقوع أي منهما.",keyIdea:"استقلال الحادثتين يستلزم استقلال المتممتين، واحتمال تقاطعهما يساوي حاصل ضرب الاحتمالين.",steps:["نحسب P(Ā)=0.7 وP(B̄)=0.6.","بما أن الحادثتين مستقلتان فإن P(Ā∩B̄)=P(Ā)P(B̄).","الناتج 0.7×0.6=0.42."],answer:"P(Ā∩B̄)=0.42",check:"احتمال عدم وقوع أي منهما هو متمم احتمال وقوع واحدة على الأقل، وهو 1−(0.3+0.4−0.12)=0.42."},
    {id:"prob-009",topic:"الاحتمالات",unit:"الاحتمالات",lesson:"احتمال شرطي",level:"متقدم",question:"إذا كان P(A∩B)=0.18 وP(B)=0.3، احسب P(A|B).",keyIdea:"الاحتمال الشرطي لـA بشرط B هو P(A∩B)/P(B) عندما P(B)>0.",steps:["نتحقق أن P(B)=0.3 غير معدوم.","نطبق P(A|B)=P(A∩B)/P(B).","نعوض 0.18/0.3 فنحصل على 0.6."],answer:"P(A|B)=0.6",check:"النتيجة بين 0 و1، وإعادة الضرب 0.6×0.3 تعطي 0.18."},
    {id:"prob-010",topic:"الاحتمالات",unit:"الاحتمالات",lesson:"توقع متغير عشوائي",level:"متوسط",question:"متغير عشوائي X يأخذ القيم 0 و1 و2 باحتمالات 0.2 و0.5 و0.3 على الترتيب. احسب E(X).",keyIdea:"الأمل الرياضي يساوي مجموع جداءات كل قيمة باحتمالها.",steps:["نتحقق أن 0.2+0.5+0.3=1.","نكتب E(X)=0×0.2+1×0.5+2×0.3.","نجمع فنحصل على 0+0.5+0.6=1.1."],answer:"E(X)=1.1",check:"مجموع الاحتمالات يساوي 1، والتوقع يقع بين أصغر قيمة وأكبر قيمة ممكنتين."}
,
{id:"lim-010",topic:"النهايات والاستمرار",unit:"النهايات والاستمرار",lesson:"نهاية تابع كسري عند اللانهاية",level:"أساسي",question:"احسب نهاية f(x)=(3x²−x+2)/(2x²+5) عندما x يؤول إلى +∞.",keyIdea:"في كسر كثيرتي حدود من الدرجة نفسها، تساوي النهاية نسبة معاملي الحدين الأعلى درجة.",steps:["نقسم البسط والمقام على x².","نحصل على (3−1/x+2/x²)/(2+5/x²).","عند x→+∞ تتلاشى الحدود التي تحوي 1/x، فالنهاية 3/2."],answer:"lim f(x)=3/2.",check:"الحدان المسيطران هما 3x² و2x²، ونسبة معامليهما 3/2."},
    {id:"lim-011",topic:"النهايات والاستمرار",unit:"النهايات والاستمرار",lesson:"نهاية فرق مربعين",level:"متوسط",question:"احسب lim عندما x→3 للتعبير (x²−9)/(x−3).",keyIdea:"نحلل فرق مربعين ونختزل العامل المشترك قبل حساب النهاية.",steps:["نكتب x²−9=(x−3)(x+3).","لـ x≠3 يصبح الكسر x+3.","إذن النهاية عندما x→3 هي 6."],answer:"النهاية تساوي 6.",check:"التعبير المختزل يقترب من 3+3=6."},
    {id:"lim-012",topic:"النهايات والاستمرار",unit:"النهايات والاستمرار",lesson:"تعيين وسيط للاستمرار",level:"متوسط",question:"ليكن f(x)=(x²−4)/(x−2) إذا x≠2 وf(2)=a. عين a لكي يكون f مستمراً عند 2.",keyIdea:"قيمة التابع عند نقطة الاستمرار تساوي نهاية التعبير عندما يقترب المتغير من تلك النقطة.",steps:["نحلل x²−4=(x−2)(x+2).","لـ x≠2 يساوي f(x) التعبير x+2، ولذلك النهاية عند 2 تساوي 4.","شرط الاستمرار يعطي a=4."],answer:"a=4.",check:"مع a=4 تتساوى النهاية وقيمة التابع عند x=2."},
    {id:"seq-010",topic:"المتتاليات",unit:"المتتاليات",lesson:"مجموع حدود متتالية هندسية",level:"متوسط",question:"متتالية هندسية حدها الأول 3 وأساسها 2. احسب مجموع حدودها الخمسة الأولى.",keyIdea:"عندما q≠1 فإن مجموع أول n حد هو u₁(qⁿ−1)/(q−1).",steps:["نعوض u₁=3 وq=2 وn=5.","S₅=3(2⁵−1)/(2−1).","نحسب S₅=3×31=93."],answer:"S₅=93.",check:"الحدود هي 3 و6 و12 و24 و48، ومجموعها 93."},
    {id:"seq-011",topic:"المتتاليات",unit:"المتتاليات",lesson:"تحديد حد متتالية حسابية من حدين",level:"أساسي",question:"في متتالية حسابية u₃=8 وu₇=20. أوجد أساسها وحدها الأول.",keyIdea:"الفرق بين حدين يساوي فرق رتبتيهما مضروباً بالأساس.",steps:["لدينا u₇−u₃=(7−3)r، أي 20−8=4r.","إذن r=3.","وبما أن u₃=u₁+2r، فإن u₁=8−6=2."],answer:"الأساس r=3 والحد الأول u₁=2.",check:"u₃=2+2×3=8 وu₇=2+6×3=20."},
    {id:"seq-limit-008",topic:"نهاية متتالية",unit:"نهاية متتالية",lesson:"نهاية متتالية جذرية بالقسمة على n",level:"متوسط",question:"احسب نهاية uₙ=√(9n²+2n)/n عندما n→+∞.",keyIdea:"بما أن n موجب، نخرج n من الجذر ونقسم على n.",steps:["نكتب uₙ=√(9+2/n)، لأن n موجب.","عندما n→+∞ فإن 2/n→0.","إذن النهاية √9=3."],answer:"lim uₙ=3.",check:"مربع النسبة تحت الجذر يقترب من 9، والنسبة موجبة."},
    {id:"der-010",topic:"الاشتقاق",unit:"الاشتقاق",lesson:"اشتقاق خارج تابعين",level:"متوسط",question:"اشتق f(x)=(x²+1)/(x−1) حيث x≠1.",keyIdea:"مشتقة خارج تابعين هي (u′v−uv′)/v² مع v غير معدوم.",steps:["نضع u=x²+1 وv=x−1، فنجد u′=2x وv′=1.","نطبق القاعدة: f′(x)=[2x(x−1)−(x²+1)]/(x−1)².","نبسط البسط فنحصل على x²−2x−1."],answer:"f′(x)=(x²−2x−1)/(x−1)².",check:"المشتقة معرفة لكل x≠1، وهو مجال التابع."},
    {id:"der-011",topic:"الاشتقاق",unit:"الاشتقاق",lesson:"دراسة إشارة المشتقة والرتابة",level:"متوسط",question:"ادرس رتابة f(x)=x²−4x+1 على R.",keyIdea:"نحدد إشارة المشتقة ثم نستنتج فترات التزايد والتناقص.",steps:["نحسب f′(x)=2x−4=2(x−2).","تكون المشتقة سالبة إذا x<2 وموجبة إذا x>2.","إذن f متناقصة على ]−∞,2] ومتزايدة على [2,+∞[."],answer:"متناقصة حتى x=2 ثم متزايدة بعده.",check:"تتغير إشارة المشتقة من السالب إلى الموجب عند 2، فتتحقق قيمة صغرى."},
    {id:"log-009",topic:"التابع اللوغاريتمي",unit:"التابع اللوغاريتمي",lesson:"حل متراجحة لوغاريتمية",level:"متوسط",question:"حل المتراجحة ln(x)>ln(4).",keyIdea:"الدالة ln متزايدة تماماً على مجالها ]0,+∞[.",steps:["مجال التعريف يفرض x>0.","بما أن ln متزايدة، نحافظ على اتجاه المتراجحة فنحصل على x>4.","نأخذ التقاطع مع المجال، فيبقى x>4."],answer:"مجموعة الحل ]4,+∞[.",check:"كل x أكبر من 4 موجب ويحقق ln(x)>ln(4)."},
    {id:"exp-009",topic:"التابع الأسي",unit:"التابع الأسي",lesson:"حل متراجحة أسية",level:"متوسط",question:"حل المتراجحة e^(2x−1)≤e³.",keyIdea:"الدالة الأسية متزايدة تماماً، لذلك نقارن الأسين مع الحفاظ على اتجاه المتراجحة.",steps:["نستعمل تزايد الدالة الأسية: 2x−1≤3.","نضيف 1 للطرفين فنحصل على 2x≤4.","نقسم على 2 فنجد x≤2."],answer:"مجموعة الحل ]−∞,2].",check:"عند x=2 يتساوى الطرفان، وللقيم الأصغر يكون الطرف الأيسر أصغر."},
    {id:"int-009",topic:"التكامل والتابع الأصلي",unit:"التكامل والتوابع الأصلية",lesson:"تكامل مجموع حدود كثيرة حدود",level:"أساسي",question:"أوجد تابعاً أصلياً للتابع f(x)=3x²−4x+2.",keyIdea:"نكامل كل حد على حدة باستعمال قاعدة تكامل القوى.",steps:["تكامل 3x² هو x³.","تكامل −4x هو −2x²، وتكامل 2 هو 2x.","إذن تابع أصلي هو F(x)=x³−2x²+2x."],answer:"F(x)=x³−2x²+2x+C.",check:"اشتقاق F يعيد 3x²−4x+2."},
    {id:"int-010",topic:"التكامل والتابع الأصلي",unit:"التكامل والتوابع الأصلية",lesson:"حساب مساحة محصورة بتابع موجب",level:"متوسط",question:"احسب مساحة المنطقة المحصورة بين منحني y=2x ومحور الفواصل والمستقيمين x=0 وx=3.",keyIdea:"عندما يكون التابع غير سالب على المجال، تساوي المساحة التكامل المحدد للتابع.",steps:["لدينا 2x≥0 على [0,3].","المساحة A=∫₀³ 2x dx.","تابع أصلي هو x²، إذن A=3²−0²=9."],answer:"المساحة 9 وحدات مربعة.",check:"المثلث قاعدته 3 وارتفاعه 6، ومساحته (3×6)/2=9."},
    {id:"vec-006",topic:"الأشعة في الفراغ",unit:"الأشعة في الفراغ",lesson:"شرط توازي شعاعين",level:"متوسط",question:"تحقق من توازي u=(2,−4,6) وv=(1,−2,3).",keyIdea:"يتوازى شعاعان إذا كانت مركبات أحدهما مضاعفاً ثابتاً لمركبات الآخر.",steps:["نقارن المركبات: 2=2×1 و−4=2×(−2) و6=2×3.","إذن u=2v.","بالتالي الشعاعان متوازيان ولهما الاتجاه نفسه."],answer:"u وv متوازيان، حيث u=2v.",check:"النسبة بين المركبات المتناظرة تساوي 2 في الحالات الثلاث."},
    {id:"dot-007",topic:"الجداء السلمي في الفراغ",unit:"الجداء السلمي في الفراغ",lesson:"حساب زاوية بين شعاعين",level:"متوسط",question:"أوجد قياس الزاوية بين u=(1,0,0) وv=(1,1,0).",keyIdea:"u·v=||u|| ||v|| cosθ، حيث θ هي الزاوية بين الشعاعين.",steps:["نحسب u·v=1، وطولا الشعاعين 1 و√2.","إذن cosθ=1/√2.","الزاوية المحصورة هي θ=π/4، أي 45 درجة."],answer:"الزاوية π/4 (45°).",check:"جيب تمام 45 درجة يساوي √2/2=1/√2."},
    {id:"line-006",topic:"المستقيمات والمستويات في الفراغ",unit:"المستقيمات والمستويات في الفراغ",lesson:"معادلة مستقيم يمر بنقطة وله شعاع توجيه",level:"متوسط",question:"اكتب تمثيلاً وسيطياً للمستقيم المار بالنقطة A(1,−2,0) وشعاع توجيهه u=(2,1,−1).",keyIdea:"كل نقطة M على المستقيم تحقق AM=t u.",steps:["نكتب (x,y,z)=(1,−2,0)+t(2,1,−1).","بمساواة المركبات نحصل على x=1+2t.","ونحصل كذلك على y=−2+t وz=−t، حيث t∈R."],answer:"x=1+2t، y=−2+t، z=−t، حيث t∈R.",check:"عند t=0 نحصل على A، ومتجه معاملات t هو (2,1,−1)."},
    {id:"line-007",topic:"المستقيمات والمستويات في الفراغ",unit:"المستقيمات والمستويات في الفراغ",lesson:"تحديد وضع مستقيم بالنسبة إلى مستوى",level:"متوسط",question:"هل المستقيم المار بـA(0,0,1) وشعاع توجيهه u=(1,1,0) موازٍ للمستوى 2x−y+z=4؟",keyIdea:"يكون اتجاه المستقيم موازياً للمستوى إذا كان شعاع توجيهه متعامداً مع ناظم المستوى.",steps:["شعاع ناظم المستوى هو n=(2,−1,1).","نحسب u·n=2−1+0=1.","بما أن الجداء غير صفري، فالمستقيم غير موازٍ للمستوى."],answer:"المستقيم ليس موازياً للمستوى، وهو يقطعه في نقطة واحدة.",check:"بالتعويض عن x=t وy=t وz=1 في المستوى نجد t+1=4، أي t=3، فتوجد نقطة تقاطع."},
    {id:"cx-009",topic:"الأعداد العقدية",unit:"الأعداد العقدية",lesson:"القوى البسيطة للعدد التخيلي",level:"أساسي",question:"احسب i²+i³+i⁴.",keyIdea:"نستعمل العلاقات الدورية لقوى i: i²=−1 وi³=−i وi⁴=1.",steps:["نعوض i²=−1.","ونعوض i³=−i وi⁴=1.","المجموع −1−i+1 يساوي −i."],answer:"i²+i³+i⁴=−i.",check:"الجزء الحقيقي −1+1 يساوي صفراً، ويبقى الجزء التخيلي −i."},
    {id:"cx-010",topic:"الأعداد العقدية",unit:"الأعداد العقدية",lesson:"قسمة عددين عقديين",level:"متوسط",question:"اكتب (1+i)/(1−i) على الشكل a+bi.",keyIdea:"نضرب البسط والمقام بمرافق المقام لجعل المقام حقيقياً.",steps:["نضرب في (1+i)/(1+i)، فنحصل على (1+i)²/(1−i²).","البسط 1+2i+i²=2i، والمقام 2.","إذن الناتج i."],answer:"(1+i)/(1−i)=i.",check:"i(1−i)=i−i²=1+i، فيتحقق الضرب العكسي."},
    {id:"complex-geometry-005",topic:"تطبيقات الأعداد العقدية",unit:"تطبيقات الأعداد العقدية في الهندسة",lesson:"التحويل بالتشابه المباشر",level:"متوسط",question:"تحويل يكتب z′=2z+1. حدد طبيعة التحويل ونسبته.",keyIdea:"التحويل z′=az+b حيث a≠0 تشابه مباشر نسبته |a|، وقد يكون تحويلاً مركباً من دوران وانسحاب.",steps:["لدينا a=2 وb=1.","نسبة التشابه هي |a|=2 وزاوية الدوران arg(2)=0.","إذن هو تشابه مباشر مركزه ثابت التحويل z₀ الذي يحقق z₀=2z₀+1، أي z₀=−1."],answer:"تشابه مباشر مركزه لاحقته −1 ونسبته 2 وزاويته 0.",check:"نقطة المركز −1 ثابتة لأن 2(−1)+1=−1."},
    {id:"comb-008",topic:"التحليل التوافقي",unit:"التحليل التوافقي",lesson:"عدد الترتيبات دون تكرار",level:"أساسي",question:"كم طريقة لترتيب 4 كتب مختلفة على رف واحد؟",keyIdea:"عدد ترتيبات n عناصر مختلفة هو n!.",steps:["للمكان الأول 4 اختيارات.","بعد اختيار الكتاب الأول تبقى 3 ثم 2 ثم 1 اختيارات.","إذن العدد 4×3×2×1=24."],answer:"24 ترتيباً.",check:"4!=24."},
    {id:"comb-009",topic:"التحليل التوافقي",unit:"التحليل التوافقي",lesson:"اختيار مجموعة دون اعتبار الترتيب",level:"أساسي",question:"كم لجنة من 3 أشخاص يمكن اختيارها من بين 7 أشخاص؟",keyIdea:"عند اختيار مجموعة لا يهم ترتيب الأعضاء، لذلك نستعمل التوافيق.",steps:["نحسب C(7,3)=7!/(3!4!).","نختزل 7×6×5/(3×2×1).","الناتج 35."],answer:"35 لجنة.",check:"كل مجموعة من ثلاثة أشخاص تحسب مرة واحدة دون تكرار الترتيبات."},
    {id:"prob-011",topic:"الاحتمالات",unit:"الاحتمالات",lesson:"احتمال المتممة",level:"أساسي",question:"إذا كان احتمال وقوع حادثة A يساوي 0.37، احسب احتمال عدم وقوعها.",keyIdea:"احتمال متممة الحادثة يساوي 1 ناقص احتمال الحادثة.",steps:["نرمز للمتممة بـ Ā.","نطبق P(Ā)=1−P(A).","إذن P(Ā)=1−0.37=0.63."],answer:"P(Ā)=0.63.",check:"مجموع احتمالي الحادثة ومتممتها يساوي 1."},
    {id:"prob-012",topic:"الاحتمالات",unit:"الاحتمالات",lesson:"احتمال تقاطع حادثتين مستقلتين",level:"متوسط",question:"حادثتان مستقلتان A وB، حيث P(A)=0.4 وP(B)=0.25. احسب P(A∩B).",keyIdea:"في حالة الاستقلال P(A∩B)=P(A)P(B).",steps:["نستعمل تعريف استقلال الحادثتين.","نحسب 0.4×0.25.","الناتج 0.10."],answer:"P(A∩B)=0.1.",check:"الاحتمال الناتج بين الصفر والأصغر من احتمالي الحادثتين."},
    {id:"prob-013",topic:"الاحتمالات",unit:"الاحتمالات",lesson:"توزيع احتمال متغير عشوائي وحساب التباين",level:"متقدم",question:"متغير عشوائي X يأخذ 0 و2 باحتمالين 0.5 و0.5. احسب E(X) وV(X).",keyIdea:"نحسب E(X)=Σxᵢpᵢ ثم V(X)=E(X²)−[E(X)]².",steps:["E(X)=0×0.5+2×0.5=1.","E(X²)=0²×0.5+2²×0.5=2.","إذن V(X)=2−1²=1."],answer:"E(X)=1 وV(X)=1.",check:"القيمتان 0 و2 متساويتا الاحتمال حول المتوسط 1، والتباين يساوي متوسط مربعي البعدين وهو 1."},
    {id:"prob-014",topic:"الاحتمالات",unit:"الاحتمالات",lesson:"استعمال قانون الاحتمال الكلي",level:"متقدم",question:"لدينا حادثتان A وĀ تشكلان تجزئة، P(A)=0.6 وP(B|A)=0.2 وP(B|Ā)=0.5. احسب P(B).",keyIdea:"قانون الاحتمال الكلي: P(B)=P(A)P(B|A)+P(Ā)P(B|Ā).",steps:["نحسب P(Ā)=1−0.6=0.4.","نعوض: P(B)=0.6×0.2+0.4×0.5.","نحصل على 0.12+0.20=0.32."],answer:"P(B)=0.32.",check:"النتيجة مجموع وزنين احتماليين، وهي بين الصفر والواحد."}

  ];

  window.solvedExamplesLibrary = Object.freeze({count:examples.length,topics:[...new Set(examples.map(item=>item.topic))],examples});

  const root = document.getElementById("formula-library");
  if (!root || document.getElementById("solved-examples-library")) return;
  const section = document.createElement("section");
  section.id = "solved-examples-library";
  section.className = "solved-examples-library";
  section.hidden = true;
  section.setAttribute("aria-labelledby", "solved-examples-title");
  section.innerHTML = `
    <div class="section-heading"><div><p class="eyebrow">تعلّم طريقة التفكير</p><h3 id="solved-examples-title">مكتبة الأمثلة المحلولة</h3><p>أمثلة تدريبية أصلية مرتبة بحسب أبحاث المنهاج ومستوى الصعوبة، مع خطوات الحل والتحقق من النتيجة.</p></div><strong id="solved-examples-count" aria-live="polite"></strong></div>
    <div class="solved-examples-controls">
      <label>ابحث في الأمثلة <input id="solved-example-search" type="search" placeholder="اكتب فكرة أو كلمة من السؤال"></label>
      <label>البحث <select id="solved-example-topic"><option value="">جميع الأبحاث</option></select></label>
      <label>المستوى <select id="solved-example-level"><option value="">جميع المستويات</option><option>أساسي</option><option>متوسط</option><option>متقدم</option></select></label>
    </div>
    <div id="solved-examples-list" class="solved-examples-list" aria-live="polite"></div>`;
  root.insertAdjacentElement("afterend", section);

  const nav = document.querySelector(".quick-start");
  if (nav) {
    const card = document.createElement("a");
    card.className = "quick-start-card";
    card.href = "#solved-examples-library";
    card.dataset.panelToggle = "solved-examples-library";
    card.setAttribute("aria-controls", "solved-examples-library");
    card.setAttribute("aria-expanded", "false");
    card.innerHTML = '<span class="quick-start-icon review-icon">✎</span><span class="quick-start-copy"><strong>الأمثلة المحلولة</strong><small>تعلّم الحل خطوة بخطوة</small></span><span class="quick-start-arrow">←</span>';
    nav.appendChild(card);
  }

  const topicSelect = section.querySelector("#solved-example-topic");
  const searchInput = section.querySelector("#solved-example-search");
  const levelSelect = section.querySelector("#solved-example-level");
  const list = section.querySelector("#solved-examples-list");
  const count = section.querySelector("#solved-examples-count");
  [...new Set(examples.map(item => item.topic))].sort((a,b)=>a.localeCompare(b,"ar")).forEach(topic => {
    const option = document.createElement("option"); option.value = topic; option.textContent = topic; topicSelect.appendChild(option);
  });

  function render() {
    const term = searchInput.value.trim().toLocaleLowerCase("ar");
    const filtered = examples.filter(item =>
      (!topicSelect.value || item.topic === topicSelect.value) &&
      (!levelSelect.value || item.level === levelSelect.value) &&
      (!term || [item.question,item.lesson,item.keyIdea,item.topic].join(" ").toLocaleLowerCase("ar").includes(term))
    );
    count.textContent = `عرض ${filtered.length} من ${examples.length} مثالاً`;
    list.replaceChildren();
    if (!filtered.length) {
      const empty = document.createElement("p"); empty.className = "solved-examples-empty"; empty.textContent = "لا توجد أمثلة مطابقة. جرّب تغيير كلمات البحث أو المرشحات."; list.appendChild(empty); return;
    }
    filtered.forEach((item,index) => {
      const article = document.createElement("article"); article.className = "solved-example-card";
      const heading = document.createElement("div"); heading.className = "solved-example-meta";
      const title = document.createElement("h4"); title.textContent = `مثال ${index+1}: ${item.lesson}`;
      const tags = document.createElement("span"); tags.textContent = `${item.topic} · ${item.level}`;
      heading.append(title,tags);
      const question = document.createElement("p"); question.className = "solved-example-question"; question.textContent = item.question;
      const idea = document.createElement("p"); idea.className = "solved-example-idea"; idea.textContent = "الفكرة الأساسية: " + item.keyIdea;
      const stepsTitle = document.createElement("strong"); stepsTitle.textContent = "خطوات الحل";
      const steps = document.createElement("ol"); item.steps.forEach(step => {const li=document.createElement("li");li.textContent=step;steps.appendChild(li);});
      const answer = document.createElement("p"); answer.className = "solved-example-answer"; answer.textContent = "النتيجة: " + item.answer;
      const check = document.createElement("p"); check.className = "solved-example-check"; check.textContent = "التحقق: " + item.check;
      article.append(heading,question,idea,stepsTitle,steps,answer,check); list.appendChild(article);
    });
    if (window.MathJax && typeof window.MathJax.typesetPromise === "function") window.MathJax.typesetPromise([list]).catch(()=>{});
  }
  [searchInput,topicSelect,levelSelect].forEach(control => control.addEventListener("input",render));
  [topicSelect,levelSelect].forEach(control => control.addEventListener("change",render));
  render();
})();
